[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-neurology",
  "answer": "제시된 4가지 소견(편측·박동성·중등도 이상·광과민·오심)은 무선조건 편두통의 임상 특징과 부합하나, IHS(ICHD) 확정 진단은 '5회 이상 발작·4~72시간·2항목 이상·1항목 이상·이차 두통 배제'의 전 항목을 문진으로 채워야 판정한다. 확정 진단 판정은 총괄이 하며, 이 SP는 항목별 충족 여부와 이차성 두통 배제 근거를 점검한다. 다만 현재 정보만으로는 발작 횟수 외 항목(지속시간·강도·악화 유발·구토 여부)이 확인되지 않아 충족 여부를 단정할 수 없다.",
  "red_flag": {
    "present": false,
    "items": []
  },
  "hypotheses": [
    {
      "name": "편두통(무선조건, Migraine without aura)",
      "icd10": "G43.0",
      "must_not_miss": false,
      "probability_band": "high",
      "supports": [
        { "text": "월 8회(월 8일 이상으로 추정) 반복되는 발작성 두통", "basis": "history" },
        { "text": "편측성", "basis": "history" },
        { "text": "박동성(욱신거림)", "basis": "history" },
        { "text": "광과민 동반", "basis": "history" },
        { "text": "오심 동반", "basis": "history" }
      ],
      "against": [
        { "text": "발작 지속시간(4~72시간) 정보 없음", "basis": "history" },
        { "text": "중등도~중증 강도·일상활동 악화 여부 정보 없음", "basis": "history" },
        { "text": "구토 여부 정보 없음(오심만 확인)", "basis": "history" },
        { "text": "이차성 두통 배제 근거 미확인(적색기 및 위험 신호 음성 여부)", "basis": "history" }
      ]
    },
    {
      "name": "긴장형 두통",
      "icd10": "G44.2",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "반복성 만성 두통의 흔한 감별", "basis": "guideline" }
      ],
      "against": [
        { "text": "편측성", "basis": "history" },
        { "text": "박동성", "basis": "history" },
        { "text": "광과민 동반", "basis": "history" }
      ]
    },
    {
      "name": "지주막하출혈 / 뇌내출혈",
      "icd10": "I60 / I61",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [],
      "against": [
        { "text": "월 8회 반복되는 발작성 경과는 단발성 출혈성 두통과 부합하지 않음", "basis": "history" }
