    { "name": "뇌영상(MRI/MRA)", "purpose": "적색기·비정형 소견 또는 편두통 예방치료 실패 시에만", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
    { "kind": "self_care", "description": "발작 일지 작성, 수면·수분·카페인·음주·공복 등 유발 요인 기록 및 회피, 어두운 조용한 환경에서 휴식", "basis": "guideline" },
    { "kind": "otc", "description": "급성기 진통제 후보 약제는 총괄·약사 확인. 동일 성분 주 2~3일 초과 복용은 과다복용 두통 위험", "basis": "guideline" },
    { "kind": "prescription_drug", "description": "예방치료(베타차단제·칼슘차단제·항경련제 계열 등)는 계열·목적만 제시. 구체 약제·용량·간격은 처방 의사·약사 확인", "basis": "guideline" },
    { "kind": "referral", "description": "발작이 월 4회 이상이거나 일상기능 저해·예방치료 검토 시 신경과 외래 의뢰", "basis": "guideline" }
  ],
  "handoff": { "better_specialty": "", "reason": "" },
